@dataclass(frozen=True)
class Section:
    name: str
    va: int
    vsize: int
    raw_ptr: int
    raw_size: int
    characteristics: int

    @property
    def raw_end(self) -> int:
        return self.raw_ptr + self.raw_size


@dataclass(frozen=True)
class RegistryEntry:
    name: str
    name_va: int
    reg_site_va: int
    id_global_va: int
    file_off_reg: int


class Image:
    def __init__(self, path: Path):
        self.path = path
        self.data = path.read_bytes()
        self.sha256 = hashlib.sha256(self.data).hexdigest()
        if len(self.data) != EXPECTED_IMAGE_SIZE:
            raise SystemExit(
                "image_size_mismatch expected=%d actual=%d"
                % (EXPECTED_IMAGE_SIZE, len(self.data))
            )
        if self.sha256 != EXPECTED_IMAGE_SHA256:
            raise SystemExit(
                "image_sha256_mismatch expected=%s actual=%s"
                % (EXPECTED_IMAGE_SHA256, self.sha256)
            )
        self.sections = self._parse_sections()

    def _parse_sections(self) -> tuple[Section, ...]:
        data = self.data
        if data[:2] != b"MZ":
            raise SystemExit("missing_mz")
        pe_off = struct.unpack_from("<I", data, 0x3C)[0]
        if data[pe_off : pe_off + 4] != b"PE\x00\x00":
            raise SystemExit("missing_pe")
        coff = pe_off + 4
        section_count = struct.unpack_from("<H", data, coff + 2)[0]
        optional_size = struct.unpack_from("<H", data, coff + 16)[0]
        optional_off = coff + 20
        if struct.unpack_from("<H", data, optional_off)[0] != 0x10B:
            raise SystemExit("not_pe32")
        image_base = struct.unpack_from("<I", data, optional_off + 28)[0]
        if image_base != IMAGE_BASE:
            raise SystemExit("image_base_mismatch")
        result = []
        table_off = optional_off + optional_size
        for index in range(section_count):
            off = table_off + index * 40
            name = data[off : off + 8].rstrip(b"\x00").decode("ascii")
            vsize, rva, raw_size, raw_ptr = struct.unpack_from(
                "<IIII", data, off + 8
            )
            characteristics = struct.unpack_from("<I", data, off + 36)[0]
            result.append(
                Section(
                    name,
                    image_base + rva,
                    vsize,
                    raw_ptr,
                    raw_size,
                    characteristics,
                )
            )
        return tuple(result)

    def section(self, name: str) -> Section:
        for section in self.sections:
            if section.name == name:
                return section
        raise SystemExit("missing_section_%s" % name)

    def va_to_off(self, va: int) -> int | None:
        for section in self.sections:
            delta = va - section.va
            if 0 <= delta < section.raw_size:
                return section.raw_ptr + delta
        return va if 0 <= va < min(s.raw_ptr for s in self.sections) else None

    def off_to_va(self, off: int) -> int | None:
        for section in self.sections:
            delta = off - section.raw_ptr
            if 0 <= delta < section.raw_size:
                return section.va + delta
        return off if 0 <= off < min(s.raw_ptr for s in self.sections) else None

    def executable_va(self, va: int) -> bool:
        for section in self.sections:
            if section.va <= va < section.va + section.raw_size:
                return bool(section.characteristics & 0x20000000)
        return False

    def cstring(self, va: int, limit: int = 512) -> str | None:
        off = self.va_to_off(va)
        if off is None:
            return None
        end = self.data.find(b"\x00", off, min(len(self.data), off + limit + 1))
        if end < 0:
            return None
        try:
            return self.data[off:end].decode("ascii")
        except UnicodeDecodeError:
            return None

    def u32(self, off: int) -> int:
        return struct.unpack_from("<I", self.data, off)[0]

    def span_hash(self, start_va: int, end_va: int) -> str:
        start_off = self.va_to_off(start_va)
        end_off = self.va_to_off(end_va)
        if start_off is None or end_off is None or end_off < start_off:
            raise SystemExit("unmapped_span")
        return hashlib.sha256(self.data[start_off:end_off]).hexdigest()


def rel32_target(call_va: int, displacement: int) -> int:
    return (call_va + 5 + displacement) & 0xFFFFFFFF


def scan_registry(image: Image) -> tuple[RegistryEntry, ...]:
    data = image.data
    text = image.section(".text")
    rows = []
    for off in range(text.raw_ptr, text.raw_end - 23):
        if data[off] != 0x68 or data[off + 5] != 0xE8:
            continue
        if data[off + 10 : off + 12] != b"\x8B\xC8":
            continue
        if data[off + 12] != 0xE8 or data[off + 17 : off + 19] != b"\x66\xA3":
            continue
        if data[off + 23] != 0xC3:
            continue
        site_va = image.off_to_va(off)
        if site_va is None:
            continue
        call_one = rel32_target(
            site_va + 5, struct.unpack_from("<i", data, off + 6)[0]
        )
        call_two = rel32_target(
            site_va + 12, struct.unpack_from("<i", data, off + 13)[0]
        )
        if call_one != ONCE_INIT_VA or call_two != ID_ASSIGN_VA:
            continue
        name_va = struct.unpack_from("<I", data, off + 1)[0]
        id_global_va = struct.unpack_from("<I", data, off + 19)[0]
        name = image.cstring(name_va)
        if name is None or re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) is None:
            raise SystemExit("invalid_registry_name_at_0x%08X" % site_va)
        rows.append(RegistryEntry(name, name_va, site_va, id_global_va, off))
    if len(rows) != 519 or len({row.name for row in rows}) != 519:
        raise SystemExit("registry_census_mismatch rows=%d" % len(rows))
    return tuple(rows)


def getter_map(image: Image) -> dict[int, tuple[int, ...]]:
    text = image.section(".text")
    found: dict[int, list[int]] = defaultdict(list)
    data = image.data
    for off in range(text.raw_ptr, text.raw_end - 6):
        if data[off : off + 2] != b"\x66\xA1" or data[off + 6] != 0xC3:
            continue
        slot_va = struct.unpack_from("<I", data, off + 2)[0]
        getter_va = image.off_to_va(off)
        if getter_va is not None:
            found[slot_va].append(getter_va)
    return {key: tuple(values) for key, values in found.items()}


def vtables_for_getter(image: Image, getter_va: int) -> tuple[tuple[int, int], ...]:
    result = []
    data = image.data
    for pointer_off in range(16, len(data) - 16, 4):
        if image.u32(pointer_off) != getter_va:
            continue
        if image.u32(pointer_off - 8) != VTABLE_MARKER_VA:
            continue
        vtable_off = pointer_off - 16
        vtable_va = image.off_to_va(vtable_off)
        if vtable_va is not None:
            result.append((vtable_va, pointer_off))
    return tuple(result)


def vtable_map_for_getters(
    image: Image, getter_values: set[int]
) -> dict[int, tuple[tuple[int, int], ...]]:
    found: dict[int, list[tuple[int, int]]] = defaultdict(list)
    data = image.data
    for pointer_off in range(16, len(data) - 0x28, 4):
        getter_va = image.u32(pointer_off)
        if getter_va not in getter_values or image.u32(pointer_off - 8) != VTABLE_MARKER_VA:
            continue
        vtable_off = pointer_off - 16
        vtable_va = image.off_to_va(vtable_off)
        if vtable_va is not None:
            found[getter_va].append((vtable_va, pointer_off))
    return {key: tuple(values) for key, values in found.items()}


def fmt_va(value: int | None) -> str:
    return "UNKNOWN" if value is None else "0x%08X" % value


def fmt_off(value: int | None) -> str:
    return "UNKNOWN" if value is None else "0x%08X" % value


def stable_key(*parts: object) -> str:
    text = "|".join(str(part) for part in parts)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


