def combat_lifecycle_claim_sha(row: dict[str, object]) -> str:
    return stable_key(
        "PF_COMBAT_LIFECYCLE_CLAIM_V1",
        *(row[column] for column in COMBAT_LIFECYCLE_CLAIM_COLUMNS),
    )


