def ground_drop_transport_row_key(row: dict[str, object]) -> str:
    if row["evidence_mode"] == "NEW_IMAGE_EVIDENCE":
        provenance_key = row["evidence_key"]
    elif row["evidence_mode"] == "CANONICAL_REFERENCE":
        provenance_key = ground_drop_transport_canonical_ref_key(row)
    else:
        raise SystemExit("ground_drop_transport_unknown_evidence_mode")
    return stable_key(
        "PF_GROUND_DROP_TRANSPORT_ROW_V1",
        row["transport_id"],
        row["claim_sha256"],
        provenance_key,
    )


