    vtable_hash, vtable_bytes = _named_span_aggregate(
        image, linked_source_rows, "vtable_va", vtable_lengths
    )
    getter_hash, getter_bytes = _named_span_aggregate(
        image, linked_source_rows, "getter_va", 7
    )
