    observed_primary_style_pushes: set[tuple[int, int]] = set()
    if primary_start_off is None or primary_end_off is None:
        invalid_labels["selector"] = "primary_selector_range_unmapped"
    else:
        primary_bytes = image.data[primary_start_off:primary_end_off]
        for index in range(len(primary_bytes) - 1):
            if primary_bytes[index] == 0x6A and 55 <= primary_bytes[index + 1] <= 63:
                observed_primary_style_pushes.add(
                    (NAME_COLOR_SELECTOR_IMAGE_SPAN[0] + index, primary_bytes[index + 1])
                )

    # path entry, style-emitting PUSH, style ID, condition, owner/input,
    # controller family, target child slot, extra support labels, nonclaim.
    specs = (
        (0x00443FE9, 0x00443FE9, 56, "receiver_is_local_CMyActor_and_ActorAttr_plus_0x98_equals_1", "CMyActor.ActorAttr", "+0x98", "CNetActor_nameboard_vtable_0x00F2CD08", "+0x54", (), "FontStyle palette/color is DATA-only"),
        (0x00443FF2, 0x00443FF2, 55, "receiver_is_local_CMyActor_and_ActorAttr_plus_0x98_not_equal_1", "CMyActor.ActorAttr", "+0x98", "CNetActor_nameboard_vtable_0x00F2CD08", "+0x54", (), "FontStyle palette/color is DATA-only"),
        (0x00444039, 0x00444039, 56, "positive_identity_pair_and_relationship_predicate_false", "runtime_actor_positive_identity__owner_class_unproved", "identity_pair_+0x78/+0x7C", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("relationship_predicate",), "Positive identity is not an IMAGE proof of owner class or controller family"),
        (0x00444071, 0x00444071, 58, "positive_identity_pair_relationship_true_and_local_context_actor_lookup_succeeds", "runtime_actor_positive_identity__owner_class_unproved", "identity_pair_+0x78/+0x7C", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("relationship_predicate",), "Positive identity is not an IMAGE proof of owner class; no gameplay relation noun is assigned"),
        (0x00444108, 0x00444113, 59, "positive_identity_pair_relationship_true_prior_lookup_not_selected_and_secondary_relation_query_true", "runtime_actor_positive_identity__owner_class_unproved", "identity_pair_and_secondary_relation_query", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("relationship_predicate",), "Positive identity is not an IMAGE proof of owner class; no gameplay relation noun is assigned"),
        (0x0044414A, 0x0044414A, 57, "positive_identity_pair_fallthrough_after_style_58_and_59_paths_with_saved_gate_false", "runtime_actor_positive_identity__owner_class_unproved", "identity_pair_and_saved_relation_gate", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("relationship_predicate",), "Positive identity is not an IMAGE proof of owner class; no gameplay relation noun is assigned"),
        (0x0044417E, 0x0044417E, 60, "signed_nonpositive_identity_pair_and_relationship_predicate_true", "runtime_actor_nonpositive_identity__owner_class_unproved", "relationship_predicate_including_BasicAttr+0x68_fallback", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("relationship_predicate", "relationship_CNetNPC_fallback"), "Nonpositive identity is not an IMAGE proof of CNetNPC or controller family"),
        (0x0044419F, 0x0044419F, 63, "signed_nonpositive_identity_pair_relationship_false_and_receiver_vslot_0x3C_true", "runtime_actor_nonpositive_identity__owner_class_unproved", "vslot+0x3C;CNetNPC_impl_BasicAttr+0x44_eq_0_and_ordered_float+0x58_le_0", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("CNetNPC_dead_predicate",), "Nonpositive identity does not prove owner class; FontStyleID 63 is not equivalent to dead"),
        (0x00444210, 0x00444210, 61, "typed_NPCAttr_associated_actor_id_nonzero_not_self_and_actor_lookup_succeeds", "runtime_actor_with_typed_NPCAttr__owner_class_unproved", "+0x98_qword(+0x98/+0x9C)", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("NPCAttr_linked_actor_branch",), "NPCAttr downcast does not prove its owner class; FontStyleID 61 is not n_AGGRO"),
        (0x00444214, 0x00444214, 63, "typed_NPCAttr_associated_actor_id_nonzero_not_self_context_available_but_actor_lookup_fails", "runtime_actor_with_typed_NPCAttr__owner_class_unproved", "+0x98_qword(+0x98/+0x9C)", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("NPCAttr_linked_actor_branch",), "NPCAttr downcast does not prove its owner class; FontStyleID 63 is not equivalent to dead"),
        (0x00444218, 0x00444218, 63, "typed_NPCAttr_associated_actor_id_nonzero_not_self_but_local_context_unavailable", "runtime_actor_with_typed_NPCAttr__owner_class_unproved", "+0x98_qword(+0x98/+0x9C)", "dynamic_nameboard_controller__CNetActor_0x00F2CD08_or_CNetNPC_0x00F2CD48", "+0x54_or_+0x50", ("NPCAttr_linked_actor_branch",), "NPCAttr downcast does not prove its owner class; FontStyleID 63 is not equivalent to dead"),
        (0x00444234, 0x00444234, 61, "typed_CNetNPC_and_AI_WANDER_n_OFFESIVE_nonzero", "CNetNPC", "AI_WANDER.n_OFFESIVE", "CNetNPC_nameboard_vtable_0x00F2CD48", "+0x50", ("CNetNPC_cast", "AI_WANDER_n_OFFESIVE_predicate"), "This path does not read n_AGGRO; FontStyleID 61 has other causes"),
        (0x00444263, 0x00444263, 61, "typed_CNetNPC_n_OFFESIVE_false_UNNAMED_runtime_state_bit_0x100_set_and_local_vslots_0x3C_0x40_both_false", "CNetNPC_runtime_actor", "+0x70_UNNAMED_runtime_state_bit_0x100", "CNetNPC_nameboard_vtable_0x00F2CD48", "+0x50", ("actor_bit_0x100_selector", "CHitResult_CMyActor_source", "CHitResult_set_actor_bit_0x100", "CMissileHitResult_CMyActor_source", "CMissileHitResult_set_actor_bit_0x100"), "Two observed HitResult writer causes are not a complete writer census; do not name this bit aggro or local-hit state"),
        (0x00444270, 0x00444270, 62, "typed_CNetNPC_n_OFFESIVE_false_and_UNNAMED_runtime_state_bit_0x100_clear", "CNetNPC_runtime_actor", "+0x70_UNNAMED_runtime_state_bit_0x100", "CNetNPC_nameboard_vtable_0x00F2CD48", "+0x50", ("actor_bit_0x100_selector", "orange_fallback"), "This does not prove a distinct monster runtime class or the gameplay noun of bit 0x100"),
    )
    common_labels = (
        "selector", "selector_direct_rel32_caller_span",
        "controller_style_store", "UILabel_FontStyleID_parser_setter",
        "NameBoard_Player_literal", "LABEL_NAME_literal",
    )
    player_labels = (
        "player_actor_nameboard_initializer", "player_controller_ctor",
        "player_controller_vtable",
        "player_controller_binder", "player_LABEL_NAME_style_sink",
    )
    npc_labels = (
        "npc_actor_nameboard_initializer", "npc_controller_ctor",
        "npc_controller_vtable", "npc_controller_binder",
        "npc_LABEL_NAME_style_sink",
    )
    expected_emissions = {
        (0x00443FE9, 0x00443FE9, 56),
        (0x00443FF2, 0x00443FF2, 55),
        (0x00444039, 0x00444039, 56),
        (0x00444071, 0x00444071, 58),
        (0x00444108, 0x00444113, 59),
        (0x0044414A, 0x0044414A, 57),
        (0x0044417E, 0x0044417E, 60),
        (0x0044419F, 0x0044419F, 63),
        (0x00444210, 0x00444210, 61),
        (0x00444214, 0x00444214, 63),
        (0x00444218, 0x00444218, 63),
        (0x00444234, 0x00444234, 61),
        (0x00444263, 0x00444263, 61),
        (0x00444270, 0x00444270, 62),
    }
    expected_primary_style_pushes = {
        (style_emit_va, style_id)
        for _path_entry_va, style_emit_va, style_id in expected_emissions
    }
    if observed_primary_style_pushes != expected_primary_style_pushes:
        invalid_labels["selector"] = "primary_fontstyle_push_census_mismatch"
    emit_counts = Counter(spec[1] for spec in specs)
    rows: list[dict[str, str]] = []
    quarantines: list[dict[str, str]] = []

    def quarantine_row(
        index: str,
        path_entry_va: int,
        style_emit_va: int,
        style_id: int,
        input_owner: str,
        evidence_key: str,
        reasons: list[str],
    ) -> None:
        field_key = "NameColorSelector@%s.FontStyleID#N" % fmt_va(path_entry_va)
        reason = ";".join(sorted(set(reasons)))
        quarantines.append(
            {
                "quarantine_key": stable_key(
                    "ATTR_QUARANTINE_NAME_COLOR", image.sha256, index,
                    path_entry_va, style_emit_va, style_id, reason,
                ),
                "candidate_row_index": index,
                "field_key": field_key,
                "wire_key": field_key,
                "class": "NameColorSelector",
                "applies_to_class": input_owner,
                "scope_status": "UNKNOWN",
                "parent_chain": "IMAGE_CONTROL_FLOW>NameColorSelector",
                "direction": "N",
                "offset": fmt_va(path_entry_va),
                "semantic_name": "primary_LABEL_NAME_FontStyleID_selection",
                "unresolved_kind": "QUARANTINED_SELECTOR_EVIDENCE",
                "quarantine_reason": reason,
                "original_evidence_key": evidence_key,
                "source": "IMAGE",
                "image_sha256": image.sha256,
                "required_next_evidence": (
                    "repair or re-derive only this selector path from the pinned IMAGE; "
                    "do not suppress unrelated selector rows"
                ),
                "suppressed_delta_keys": "",
                "suppressed_conflict_keys": "",
                "suppressed_a2_delta_keys": "",
            }
        )

    for index, (
        path_entry_va, style_emit_va, style_id, condition, input_owner, input_offset,
        controller_family, child_slot, extra_labels, nonclaim,
    ) in enumerate(specs, 1):
        path_entry_off = image.va_to_off(path_entry_va)
        style_emit_off = image.va_to_off(style_emit_va)
        if controller_family.startswith("CNetActor_nameboard"):
            selector_lane = "typed_CMyActor_local"
            group_labels = player_labels
        elif controller_family.startswith("CNetNPC_nameboard"):
            selector_lane = "typed_CNetNPC"
            group_labels = npc_labels
        else:
            selector_lane = "untyped_dynamic_controller"
            group_labels = player_labels + npc_labels
        labels = common_labels + group_labels + tuple(extra_labels)
        row_errors = [invalid_labels[label] for label in labels if label in invalid_labels]
        selector_start, selector_end, selector_hash = NAME_COLOR_SELECTOR_IMAGE_SPAN
        if not (
            selector_start <= path_entry_va < selector_end
            and selector_start <= style_emit_va < selector_end
        ):
            row_errors.append("path_or_emit_outside_selector_range")
        if path_entry_off is None or style_emit_off is None:
            row_errors.append("unmapped_path_or_emit_va")
        elif image.data[style_emit_off:style_emit_off + 2] != bytes((0x6A, style_id)):
            row_errors.append("style_push_mismatch")
        if emit_counts[style_emit_va] != 1:
            row_errors.append("style_emit_va_not_unique")
        if (path_entry_va, style_emit_va, style_id) not in expected_emissions:
            row_errors.append("unexpected_path_emit_style_triple")
        support_text = ";".join(
            verified_support[label] for label in labels if label in verified_support
        )
        selector_key = stable_key(
            "IMAGE_NAME_COLOR_SELECTOR", image.sha256, path_entry_va, style_emit_va,
            style_id, condition, controller_family, child_slot,
        )
        evidence_key = stable_key(
            "IMAGE", image.sha256, selector_key, selector_hash,
            support_text,
        )
        if row_errors:
            quarantine_row(
                "NAME_COLOR_%02d" % index, path_entry_va, style_emit_va,
                style_id, input_owner, evidence_key, row_errors,
            )
            continue
        rows.append(
            {
                "selector_key": selector_key,
                "selector_lane": selector_lane,
                "function_va": fmt_va(selector_start),
                "function_file_offset": fmt_off(image.va_to_off(selector_start)),
                "path_entry_va": fmt_va(path_entry_va),
                "path_entry_file_offset": fmt_off(path_entry_off),
                "style_emit_va": fmt_va(style_emit_va),
                "style_emit_file_offset": fmt_off(style_emit_off),
                "condition": condition,
                "input_owner_class": input_owner,
                "input_offset_or_key": input_offset,
                "controller_family": controller_family,
                "output_vtable_slot": "+0x34",
                "output_storage_offset": "controller+0x34",
                "output_fontstyle_id": str(style_id),
                "target_controller_child_slot": child_slot,
                "target_widget_resource": "NameBoard_Player",
                "target_widget_label": "LABEL_NAME",
                "semantic_name": "primary_LABEL_NAME_FontStyleID_selection",
                "semantic_status": "PROVEN_EXACT",
                "nonclaim": nonclaim,
                "evidence_span_start": fmt_va(NAME_COLOR_SELECTOR_IMAGE_SPAN[0]),
                "evidence_span_end": fmt_va(NAME_COLOR_SELECTOR_IMAGE_SPAN[1]),
                "evidence_span_sha256": NAME_COLOR_SELECTOR_IMAGE_SPAN[2],
                "support_spans": support_text,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "blocker": (
                    "this path does not prove the runtime owner/controller class"
                    if selector_lane == "untyped_dynamic_controller" else ""
                ),
                "required_next_evidence": (
                    "exhaustive IMAGE sign/identity-to-class proof or a typed call path"
                    if selector_lane == "untyped_dynamic_controller" else ""
                ),
                "image_sha256": image.sha256,
            }
        )
    observed_emissions = {(spec[0], spec[1], spec[2]) for spec in specs}
    for missing_index, (path_entry_va, style_emit_va, style_id) in enumerate(
        sorted(expected_emissions - observed_emissions), 1
    ):
        evidence_key = stable_key(
            "IMAGE_NAME_COLOR_MISSING_EXPECTED", image.sha256,
            path_entry_va, style_emit_va, style_id,
        )
        quarantine_row(
            "NAME_COLOR_MISSING_%02d" % missing_index,
            path_entry_va, style_emit_va, style_id,
            "UNKNOWN_RUNTIME_ACTOR", evidence_key,
            ["missing_expected_path_emit_style_triple"],
        )
    style_counts = Counter(int(row["output_fontstyle_id"]) for row in rows)
    if (
        len({row["selector_key"] for row in rows}) != len(rows)
        or len({row["path_entry_va"] for row in rows}) != len(rows)
        or len({row["style_emit_va"] for row in rows}) != len(rows)
        or len({row["evidence_key"] for row in rows}) != len(rows)
        or Counter(row["source"] for row in rows) != Counter({"IMAGE": len(rows)})
        or any(row["output_vtable_slot"] != "+0x34" for row in rows)
        or any(row["image_sha256"] != image.sha256 for row in rows)
        or len({row["quarantine_key"] for row in quarantines}) != len(quarantines)
    ):
        raise SystemExit("name_color_selector_census_or_duplicate_mismatch")
    if not quarantines and (
        len(rows) != 14
        or Counter(row["selector_lane"] for row in rows)
        != Counter(
            {
                "typed_CMyActor_local": 2,
                "typed_CNetNPC": 3,
                "untyped_dynamic_controller": 9,
            }
        )
        or style_counts
        != Counter({55: 1, 56: 2, 57: 1, 58: 1, 59: 1, 60: 1, 61: 3, 62: 1, 63: 3})
    ):
        raise SystemExit("name_color_selector_golden_census_mismatch")
    return rows, quarantines


