    def assert_direct_call(label: str, call_va: int, expected_target: int) -> None:
        off = image.va_to_off(call_va)
        if off is None or image.data[off] != 0xE8:
            raise SystemExit("quest_mark_missing_direct_call_%s" % label)
        displacement = struct.unpack_from("<i", image.data, off + 1)[0]
        if rel32_target(call_va, displacement) != expected_target:
            raise SystemExit("quest_mark_direct_call_target_mismatch_%s" % label)

    def assert_bytes(label: str, va: int, expected: bytes) -> None:
        off = image.va_to_off(va)
        if off is None or image.data[off : off + len(expected)] != expected:
            raise SystemExit("quest_mark_instruction_mismatch_%s" % label)

    def assert_utf16(label: str, va: int, expected: str) -> str:
        off = image.va_to_off(va)
        raw = expected.encode("utf-16le") + b"\x00\x00"
        if off is None or image.data[off : off + len(raw)] != raw:
            raise SystemExit("quest_mark_literal_mismatch_%s" % label)
        return expected

    def assert_ascii(label: str, va: int, expected: str) -> str:
        off = image.va_to_off(va)
        raw = expected.encode("ascii") + b"\x00"
        if off is None or image.data[off : off + len(raw)] != raw:
            raise SystemExit("quest_mark_ascii_literal_mismatch_%s" % label)
        return expected

    def parse_u16_local_member_assignment(
        label: str, va: int, expected: bytes, local_index: int, member_index: int
    ) -> tuple[int, int]:
        assert_bytes(label, va, expected)
        return expected[local_index], expected[member_index]

    def parse_cmp_eax_imm8(label: str, va: int) -> int:
        off = image.va_to_off(va)
        if off is None or image.data[off:off + 2] != b"\x83\xF8":
            raise SystemExit("quest_mark_cmp_eax_signature_mismatch_%s" % label)
        return image.data[off + 2]

    def parse_test_eax_zero(label: str, va: int) -> int:
        off = image.va_to_off(va)
        if off is None or image.data[off:off + 2] != b"\x85\xC0":
            raise SystemExit("quest_mark_test_eax_signature_mismatch_%s" % label)
        return 0

    def parse_push_imm32(label: str, va: int) -> int:
        off = image.va_to_off(va)
        if off is None or image.data[off] != 0x68:
            raise SystemExit("quest_mark_push_imm32_signature_mismatch_%s" % label)
        return struct.unpack_from("<I", image.data, off + 1)[0]

