                mob_id,
                line_by_id[mob_id],
                integer(row, "n_RANK"),
                integer(row, "n_AI_WANDER"),
                integer(row, "n_AI_COMBAT"),
                integer(row, "n_AI_TACTIC"),
                integer(row, "n_MOB_USAGE"),
