    service_ids = (156, 248, 447, 483)
    if any(
        integer(mobs_by_id[mob_id], "n_MOB_USAGE") != 2
        or not capability_flag(mobs_by_id[mob_id])
        or not quest_flag(mobs_by_id[mob_id])
        or rank_flag(mobs_by_id[mob_id])
        or combat_flag(mobs_by_id[mob_id])
        or offensive_flag(mobs_by_id[mob_id])
        for mob_id in service_ids
    ):
        raise SystemExit("role_discriminator_service_sample_mismatch")
    add_data(
        "MOBS_USAGE2_KQ_CLUSTER",
        "DATA_CLUSTER",
        "MOBS.n_MOB_USAGE=2+n_CAPABILITY+quest_vectors",
        "empirical_usage_capability_quest_cluster",
        "MOBS",
        "usage=2, capability=1, and quest vector nonempty",
        "cluster_total=670;rank_positive=12;combat_nonzero=10;offensive=8;"
        "sample_ids_zero_R_C_O=156,248,447,483",
        "cluster_rows=670",
        "PROVEN_COUNT_ONLY",
        "columns=11,18,19,38,39,40,49",
        "The composite is a strong DATA cluster, but the table contains no "
        "talkability or service-role law.",
        "Rank, combat, and offensive overlap does not by itself falsify a mixed service role.",
        "Treat as a proposed reconstruction input only, with explicit exceptions.",
    )

    row_by_id = {row["discriminator_id"]: row for row in rows}
    if len(row_by_id) != len(rows):
        raise SystemExit("role_discriminator_duplicate_id_before_reuse_link")
    for row in rows:
        row["evidence_reuse"] = "NEW_CLAIM"
        row["derived_from_artifact"] = "N/A"
        row["derived_from_row_key"] = "N/A"
        row["derived_from_claim_digest"] = "N/A"
        row["derived_claim_fragment"] = "N/A"

    npc_template_rows = [
        row
        for row in field_rows
        if row.get("class") == "NPCAttr"
        and row.get("offset") == "0x78"
        and row.get("applies_to_class") == "CNetNPC"
    ]
    npc_enemy_rows = [
        row
        for row in field_rows
        if row.get("class") == "BasicAttr"
        and row.get("offset") == "0x6C"
        and row.get("applies_to_class") == "CNetNPC"
    ]
    offensive_selector_rows = [
        row
        for row in name_color_rows
        if row.get("condition")
        == "typed_CNetNPC_and_AI_WANDER_n_OFFESIVE_nonzero"
    ]
    schema_binding_rows = [
        row
        for row in data_binding_rows
        if (row.get("subject_class"), row.get("subject_key"))
        in {("MOBS_DATA", "schema"), ("AI_WANDER_DATA", "schema")}
    ]
    if (
        len(npc_template_rows) != 2
        or {row.get("direction") for row in npc_template_rows} != {"R", "W"}
        or any(
            row.get("semantic_name") != "npc_mobs_template_id"
            or row.get("semantic_status") != "PROVEN_EXACT"
            or row.get("scope_status") != "PROVEN_EXACT"
            or row.get("source") != "IMAGE"
            for row in npc_template_rows
        )
        or len(npc_enemy_rows) != 2
        or {row.get("direction") for row in npc_enemy_rows} != {"R", "W"}
        or any(
            row.get("semantic_name") != "CNetNPC.template.n_ENEMY"
            or row.get("semantic_status") != "PROVEN_EXACT"
            or row.get("scope_status") != "PROVEN_EXACT"
            or row.get("source") != "IMAGE"
            for row in npc_enemy_rows
        )
        or len(offensive_selector_rows) != 1
        or offensive_selector_rows[0].get("semantic_name")
        != "primary_LABEL_NAME_FontStyleID_selection"
        or offensive_selector_rows[0].get("semantic_status") != "PROVEN_EXACT"
        or offensive_selector_rows[0].get("source") != "IMAGE"
        or len(schema_binding_rows) != 2
        or {
            (row.get("subject_class"), row.get("semantic_name"))
            for row in schema_binding_rows
        }
        != {
            ("MOBS_DATA", "MOBS_column_census"),
            ("AI_WANDER_DATA", "AI_WANDER_column_and_directive_census"),
        }
        or any(
            row.get("semantic_status") != "PROVEN_EXACT"
            or row.get("source") != "DATA"
            for row in schema_binding_rows
        )
        or any(
            len(row.get("evidence_key", "")) != 64
            for row in npc_template_rows
            + npc_enemy_rows
            + offensive_selector_rows
            + schema_binding_rows
        )
    ):
        raise SystemExit("role_discriminator_canonical_reuse_source_mismatch")

    def link_canonical(
        row_id: str,
        artifact: str,
        canonical_rows: list[dict[str, str]],
        claim_fragment: str,
    ) -> None:
        row = row_by_id[row_id]
        canonical_pairs = sorted(
            (
                canonical_row["evidence_key"],
                canonical_tsv_row_digest(
                    artifact,
                    canonical_columns_by_artifact[artifact],
                    canonical_row,
                ),
            )
            for canonical_row in canonical_rows
        )
        row["evidence_reuse"] = "PARTIAL_CANONICAL_REUSE"
        row["derived_from_artifact"] = artifact
        row["derived_from_row_key"] = ";".join(
            key for key, _digest in canonical_pairs
        )
        row["derived_from_claim_digest"] = ";".join(
            digest for _key, digest in canonical_pairs
        )
        row["derived_claim_fragment"] = claim_fragment

    link_canonical(
        "CNETNPC_TEMPLATE_ATTACHMENT",
        "PF_ATTR_FIELD_SEMANTICS.tsv",
        npc_template_rows,
        "typed_CNetNPC_NPCAttr+0x78_template_id_directional_rows_only",
    )
    link_canonical(
        "AI_WANDER_OFFESIVE_NAMEBOARD",
        "PF_ATTR_NAME_COLOR_SELECTOR.tsv",
        offensive_selector_rows,
        "typed_CNetNPC_n_OFFESIVE_nameboard_selector_only",
    )
    link_canonical(
        "MOBS_N_ENEMY_LOADED_COPY",
        "PF_ATTR_FIELD_SEMANTICS.tsv",
        npc_enemy_rows,
        "typed_CNetNPC_BasicAttr+0x6C_n_ENEMY_directional_rows_only",
    )
    link_canonical(
        "MOBS_SCHEMA_CENSUS",
        "PF_ATTR_DATA_BINDINGS.tsv",
        schema_binding_rows,
        "MOBS_and_AI_WANDER_schema_census_only",
    )

    claim_fields = (
        "discriminator_id",
        "discriminator_key",
        "evidence_key",
        "row_kind",
        "role_field_key",
        "axis",
        "subject",
        "input_or_condition",
        "exact_observation",
        "measured_count",
        "semantic_status",
        "scope",
        "evidence_file",
        "evidence_file_sha256",
        "evidence_locator",
        "evidence_span_start",
        "evidence_span_end",
        "evidence_span_sha256",
        "support_spans",
        "evidence_reuse",
        "derived_from_artifact",
        "derived_from_row_key",
        "derived_from_claim_digest",
        "derived_claim_fragment",
        "source",
        "nonclaim",
        "blocker",
        "required_next_evidence",
        "image_sha256",
    )

    def role_claim_hash(row: dict[str, str]) -> str:
        return stable_key(
            "ATTR_ROLE_CLAIM_V1",
            *(row[field] for field in claim_fields),
        )

    for row in rows:
        row["claim_sha256"] = role_claim_hash(row)

    # Independently pinned semantic census.  These values are intentionally not
    # computed from the rows during validation: an authored claim change must
    # fail until its evidence and the golden review are deliberately re-pinned.
    golden_claim_sha256 = {
        "ACTOR_FACTORY_CLASS_DOMAIN": "48776f5a398f727720f945c049f36b6ac66fb8ac50ee798908b78537f02b69e4",
        "CNETNPC_TEMPLATE_ATTACHMENT": "f4e57a851afbcd9e6fd10dcb29934aec98961489891cf31282110cb1930a0995",
        "CNETNPC_INTERACTION_CHOOSE_NPC_GENERIC": "86173101641aaf549337c32264c7285c1fe469b20d9f4b57842941b510227562",
        "CNETNPC_INTERACTION_ACTION_GATE": "bcb17acf39008af97f104d92b1d6a39e421b22cfcadc26a370773960f608da85",
        "RELATION_FALSE_ENEMY_TARGET": "b6f7f71d87b6031d151ad7eeea93d8f7931e6615c36f48cc07edfa9198528c27",
        "ENEMY_TARGET_EA7D_ACTIONVITAL": "496d3cc02c5de4c3239f6bde7524caee009155f55001826e4f7982177a47dbbf",
        "TARGETVITAL_RELATION_KIND": "f5bc4aa98d44bd92b432e67c793447677e8819d3270e8c80c14e38d8ac9282f9",
        "MOBS_RANK_BOSS_UI": "df9c937ec177e25db9466d0405f2b95bfd7402f713095bb21c20897ee83edb11",
        "AI_WANDER_OFFESIVE_NAMEBOARD": "fa1274e8a89a4726dc02061534f435cb42de468b54853217fbc1c5e88623e52b",
        "MOBS_N_AI_COMBAT_LOADER_ONLY": "ea8e6e288d7eeaf32245780a6ebd3701ee0e849d5dabcd3c3717bd1def9f0690",
        "MOBS_N_MOB_USAGE_LITERAL_NEGATIVE": "36c9274a30824d268ff361f006e89514a579af019b8367269adf0b993b67d135",
        "MOBS_N_CAPABILITY_UI_DATA_GATE": "24cc5de4b0586978ee71a0e2719c88500c0b726a0be2c958edc648d594fe6aea",
        "MOBS_N_ENEMY_LOADED_COPY": "f4dd1757709720a4a9e0e81da0449912fd7f26a897423a47a99046f9c6a2978b",
        "ACTOR_DEATH_SHARED": "323748a946dcd867a98be5b347b80655c9c161685bafaac408ccd4a2f27d5ddd",
        "MOBS_DROP_CONFIG": "7eddb2d5d46200b59e4898cb72953d3e4831eb8eaede28f8f8483c005225fda3",
        "MOBS_SCHEMA_CENSUS": "5de62fd8517fd720f520f4423e5c98f9571a04dced848f658060387db4ed7260",
        "MOBS_RANK_VALUE_DOMAIN": "c05590272535ca6e1268b445aa3a17ace2fe104e4d70d58f94eab867b7166930",
        "MOBS_USAGE_VALUE_DOMAIN": "39168c0e09b7369589dd44991a4320091675e1664aa93ba57e2bc48b53a330e4",
        "MOBS_RANK_COMBAT_CROSS": "7f7621a88e675aff29253fbaa5459f5d6c96ea9dc7d9a8b573aa52bb7df84943",
        "MOBS_OFFESIVE_WEIGHTED_CROSS": "6be00acea321d43dcb58527da89b7752aa1ba965dba387a24c8bc3d1d6e419fd",
        "MOBS_CAPABILITY_QUEST_CROSS": "276b84804d8c700f3d99f3f3fe223e3ae3da17740b19a9dd7121beef75897c5d",
        "MOBS_ORDINARY_DROP_POPULATION": "457bb127a6e90c305bd5a25ba88ec204c8c9c247df5f26f501b30deaa832ba6f",
        "MOBS_ID916_FINGERPRINT": "336e01a3e400c9d74ab7ee580f6853dfe9125a260b8610e2bb37981b6025d5d2",
        "MOBS_ID917_FINGERPRINT": "5289a5e0db3b67652c017601ac9bb61d2fad50ed1cf7dfa596c4f4f3123fe96b",
        "MOBS_SAME_NAME_VARIANCE_27_1732_8621": "cfb5e8168c3cfacf327a28ad70d66d402388ce670ed18b624cc833bb4d941c38",
        "MOBS_SAME_NAME_VARIANCE_31_1635_2127": "48b4eaca4d2ef8476aaf3f9bb67c0781645ea74b89a478e7e69a46cdc0445aa9",
        "MOBS_USAGE1_RC_CLUSTER": "a093ef7ba1578d9165d188d797ccba3ab00aae64a082c44a223c56c7b2fe4a73",
        "MOBS_USAGE2_KQ_CLUSTER": "f5325cec52077563a172092c9605b4af77c083b180b1a388ba78704fc31a8b92",
    }

    def fixed_golden_matches(candidate_rows: list[dict[str, str]]) -> bool:
        return {
            row["discriminator_id"]: row["claim_sha256"]
            for row in candidate_rows
        } == golden_claim_sha256

    data_claim_fields = (
        "input_or_condition",
        "exact_observation",
        "measured_count",
        "nonclaim",
        "blocker",
        "required_next_evidence",
    )
    foreign_layer_tokens = (
        "IMAGE",
        "CNetNPC",
        "EA7D",
        "ChooseNPC",
        "ActionVital",
        "boss-UI",
        "original-client",
    )
    for row in rows:
        if row["source"] == "DATA":
            data_claim_text = "\n".join(row[field] for field in data_claim_fields)
            if any(token in data_claim_text for token in foreign_layer_tokens):
                raise SystemExit(
                    "role_discriminator_data_layer_vocabulary_leak_%s"
                    % row["discriminator_id"]
                )

    expected_row_ids = {
        "ACTOR_FACTORY_CLASS_DOMAIN",
        "CNETNPC_TEMPLATE_ATTACHMENT",
        "CNETNPC_INTERACTION_CHOOSE_NPC_GENERIC",
        "CNETNPC_INTERACTION_ACTION_GATE",
        "RELATION_FALSE_ENEMY_TARGET",
        "ENEMY_TARGET_EA7D_ACTIONVITAL",
        "TARGETVITAL_RELATION_KIND",
        "MOBS_RANK_BOSS_UI",
        "AI_WANDER_OFFESIVE_NAMEBOARD",
        "MOBS_N_AI_COMBAT_LOADER_ONLY",
        "MOBS_N_MOB_USAGE_LITERAL_NEGATIVE",
        "MOBS_N_CAPABILITY_UI_DATA_GATE",
        "MOBS_N_ENEMY_LOADED_COPY",
        "ACTOR_DEATH_SHARED",
        "MOBS_DROP_CONFIG",
        "MOBS_SCHEMA_CENSUS",
        "MOBS_RANK_VALUE_DOMAIN",
        "MOBS_USAGE_VALUE_DOMAIN",
        "MOBS_RANK_COMBAT_CROSS",
        "MOBS_OFFESIVE_WEIGHTED_CROSS",
        "MOBS_CAPABILITY_QUEST_CROSS",
        "MOBS_ORDINARY_DROP_POPULATION",
        "MOBS_ID916_FINGERPRINT",
        "MOBS_ID917_FINGERPRINT",
        "MOBS_SAME_NAME_VARIANCE_27_1732_8621",
        "MOBS_SAME_NAME_VARIANCE_31_1635_2127",
        "MOBS_USAGE1_RC_CLUSTER",
        "MOBS_USAGE2_KQ_CLUSTER",
    }

    def role_rows_valid(candidate_rows: list[dict[str, str]]) -> bool:
        canonical_reuse_ids = {
            "CNETNPC_TEMPLATE_ATTACHMENT",
            "AI_WANDER_OFFESIVE_NAMEBOARD",
            "MOBS_N_ENEMY_LOADED_COPY",
            "MOBS_SCHEMA_CENSUS",
        }
        return (
            len(candidate_rows) == 28
            and Counter(row["source"] for row in candidate_rows)
            == Counter({"IMAGE": 15, "DATA": 13})
            and len({row["discriminator_key"] for row in candidate_rows})
            == len(candidate_rows)
            and len({row["evidence_key"] for row in candidate_rows})
            == len(candidate_rows)
            and {row["discriminator_id"] for row in candidate_rows}
            == expected_row_ids
            and all(
                row["discriminator_key"]
                == stable_key("ATTR_ROLE_DISCRIMINATOR", row["evidence_key"])
                for row in candidate_rows
            )
            and all(
                row["claim_sha256"] == role_claim_hash(row)
                for row in candidate_rows
            )
            and fixed_golden_matches(candidate_rows)
            and all(
                row["required_next_evidence"].startswith("PROPOSED: ")
                for row in candidate_rows
            )
            and {
                row["discriminator_id"]
                for row in candidate_rows
                if row["evidence_reuse"] == "PARTIAL_CANONICAL_REUSE"
            }
            == canonical_reuse_ids
            and all(
                (
                    row["derived_from_artifact"] != "N/A"
                    and row["derived_from_row_key"] != "N/A"
                    and row["derived_from_claim_digest"] != "N/A"
                    and row["derived_claim_fragment"] != "N/A"
                )
                if row["discriminator_id"] in canonical_reuse_ids
                else (
                    row["evidence_reuse"] == "NEW_CLAIM"
                    and row["derived_from_artifact"] == "N/A"
                    and row["derived_from_row_key"] == "N/A"
                    and row["derived_from_claim_digest"] == "N/A"
                    and row["derived_claim_fragment"] == "N/A"
                )
                for row in candidate_rows
            )
            and all(
                row["source"] != "IMAGE"
                or (
                    row["image_sha256"] == image.sha256
                    and row["evidence_file_sha256"] == image.sha256
                )
                for row in candidate_rows
            )
            and all(
                row["source"] != "DATA"
                or (
                    row["image_sha256"] == "N/A"
                    and row["evidence_file_sha256"] == const_packed_hash
                )
                for row in candidate_rows
            )
            and all(
                all(str(value).isascii() for value in row.values())
                for row in candidate_rows
            )
        )

    mutated_rows = [dict(row) for row in rows]
    mutated_rows[0]["exact_observation"] += " MUTATED"
    rehashed_mutated_rows = [dict(row) for row in rows]
    rehashed_mutated_rows[0]["exact_observation"] += " MUTATED_REHASHED"
    rehashed_mutated_rows[0]["claim_sha256"] = role_claim_hash(
        rehashed_mutated_rows[0]
    )
    fabricated_evidence_rows = [dict(row) for row in rows]
    fabricated_evidence_rows[0]["evidence_key"] = "0" * 64
    fabricated_evidence_rows[0]["discriminator_key"] = stable_key(
        "ATTR_ROLE_DISCRIMINATOR",
        fabricated_evidence_rows[0]["evidence_key"],
    )
    fabricated_evidence_rows[0]["claim_sha256"] = role_claim_hash(
        fabricated_evidence_rows[0]
    )
    canonical_digest_mutated_rows = [dict(row) for row in rows]
    canonical_row = next(
        row
        for row in canonical_digest_mutated_rows
        if row["evidence_reuse"] == "PARTIAL_CANONICAL_REUSE"
    )
    canonical_row["derived_from_claim_digest"] = "0" * 64
    canonical_row["claim_sha256"] = role_claim_hash(canonical_row)
    if (
        not role_rows_valid(rows)
        or role_rows_valid(mutated_rows)
        or role_rows_valid(rehashed_mutated_rows)
        or role_rows_valid(fabricated_evidence_rows)
        or role_rows_valid(canonical_digest_mutated_rows)
    ):
        raise SystemExit("role_discriminator_census_or_source_mismatch")
    return rows


