def _assert_bytes(image: Image, va: int, expected_hex: str, label: str) -> None:
    expected = bytes.fromhex(expected_hex)
    off = image.va_to_off(va)
    if off is None or image.data[off : off + len(expected)] != expected:
        raise SystemExit("image_byte_assertion_mismatch_%s" % label)


def build_cskill_codec_corrections(
    image: Image,
) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    codec_start, codec_end = 0x007520B0, 0x00752281
    codec_hash = image.span_hash(codec_start, codec_end)
    if codec_hash != "9227cc6009fff2f20c79a3b19c395f9623d87f68a4ee3462e541aed62aa7e906":
        raise SystemExit("cskill_codec_span_hash_mismatch")
    support_spans = (
        (0x00751B90, 0x00751BEA, "3abf69326a7a821bdecd8146e3e10094fbe17086eca54ead65b30124e905bcc4"),
        (0x004B8D90, 0x004B8E13, "a268638f18e7d92399f42a52f4e6ddda6e556b667bc72c4096f71abd9ddad6d5"),
        (0x005D28A0, 0x005D28E7, "9c20362a1f04e34a35b246d91e39c870c79b626d981bf726d2abfced162d1e61"),
        (0x00751FC0, 0x007520AF, "8968da355afea6db7381ca0afb164f24af547fd53c0433cf3aa2b19cbaccae1d"),
        (0x004328C2, 0x00432A1A, "48d6d72bcbe3c0e62750eae148d226129616f5a7f1b952f541f879c9009a4b98"),
        (0x007523D0, 0x00752437, "0ad083636dbf0d785b3d574df71cf201944379a60bee6d69cd78923f6ca3866f"),
        (0x00752440, 0x007524A6, "ae9f723f4adc625bf2e207e7bc8f0e7ead00e1dc1997fd0d4394f301f9df840e"),
        (0x007524B0, 0x0075252E, "47df63ff95cca406f7fe0d3130d453d68b17e2302d733547cab7893cdcb86797"),
        (0x00754450, 0x00754712, "34a12de2be09fe615e308c30f53e999b43d26ed8306837611ce9e20debf2e323"),
        (0x00753FE0, 0x0075416F, "14b162ee7f412866163c06aa47bead334e4b12ec99bf71aa23c25ef7333113e1"),
        (0x00754280, 0x0075432E, "c5734671cb2f3941d26840e898fef8f1c210405c30eb255de257aa9254d76c5b"),
        (0x00752C00, 0x00752C54, "3c361d40abeaffc12d56e6e7034584b68224dceb29565a4b5545c2f9070c1a9b"),
        (0x00755681, 0x00755718, "a4f12ed1aac069ec1a347236dd31143232edc05fb55b6a58a52f3f4fba72eb58"),
        (0x0075588B, 0x00755908, "4f8e940ff8f77b4e0035a00386b6f40d8892b0b204c2dccc5fc366ace36976d6"),
    )
    for start, end, expected in support_spans:
        if image.span_hash(start, end) != expected:
            raise SystemExit("cskill_support_span_hash_mismatch_0x%08X" % start)
    for va, expected_hex, label in (
        (0x007520D3, "0fb7461c", "count_load"),
        (0x007520E6, "e815851400", "count_write_call"),
        (0x00752117, "3b5c2414", "write_iterator_gate"),
        (0x0075213C, "0fb74b0c", "record_key_load"),
        (0x0075214F, "e8ac841400", "record_key_write_call"),
        (0x0075216D, "8d4310", "payload_u16_address"),
        (0x00752175, "e886841400", "payload_u16_write_call"),
        (0x00752191, "83c314", "payload_u32_address"),
        (0x00752199, "e862841400", "payload_u32_write_call"),
        (0x00752205, "e836841400", "count_read_call"),
        (0x0075220C, "663b4c2440", "read_loop_first_check"),
        (0x0075221E, "e81d841400", "record_key_read_call"),
        (0x0075222E, "e80d841400", "payload_u16_read_call"),
        (0x0075223E, "e8fd831400", "payload_u32_read_call"),
        (0x0075226A, "e851fdffff", "record_insert_call"),
        (0x00752270, "663b5c2440", "read_loop_repeat_check"),
        (0x004B8DF7, "c7461c00000000", "stored_size_ctor_zero"),
        (0x00751E3E, "015f1c", "stored_size_insert_increment"),
        (0x007521DF, "895e1c", "stored_size_read_clear"),
    ):
        _assert_bytes(image, va, expected_hex, label)

    base_hash = _sha256_path(BASE_SLOT34_A2_PATH)
    if base_hash != "1778728a2d4ec53562a51ea0361bca530942f48d0f49af18b295f1ff6a49c334":
        raise SystemExit("frozen_slot34_base_hash_mismatch")
    with BASE_SLOT34_A2_PATH.open("r", encoding="utf-8", newline="") as handle:
        base_rows = list(csv.DictReader(handle, delimiter="\t"))
    by_key = {row["delta_key"]: row for row in base_rows}
    expected_keys = set(CSKILL_REMOVE_KEYS) | {spec[0] for spec in CSKILL_FIELD_SPECS}
    if len(expected_keys) != 28 or any(
        key not in by_key or by_key[key].get("message") != "CSkillAttr"
        for key in expected_keys
    ):
        raise SystemExit("cskill_frozen_row_key_census_mismatch")

    support_hashes = ";".join(span[2] for span in support_spans)
    corrections: list[dict[str, str]] = []
    for base_key in CSKILL_REMOVE_KEYS:
        prior = by_key[base_key]
        base_ref = "PF_A2_SERIALIZER_SLOT34_DELTA.tsv|%s" % base_key
        correction_key = stable_key(
            "A2_CSKILL_CORRECTION", base_ref, "REMOVE_NON_WIRE_CONTROL_FLOW_ROW", codec_hash
        )
        evidence_key = stable_key(
            "IMAGE", image.sha256, base_ref, "NOT_WIRE", codec_hash, support_hashes
        )
        corrections.append(
            {
                "correction_key": correction_key,
                "conflict_key": stable_key("ATTR_CONFLICT", correction_key),
                "base_row_ref": base_ref,
                "direction": prior["direction(W/R)"],
                "delta_action": "REMOVE_NON_WIRE_CONTROL_FLOW_ROW",
                "prior_order": prior["new_order"],
                "prior_tag": prior["new_tag"],
                "prior_field_offset": prior["new_field_offset"],
                "prior_gate": prior["new_gate_condition"],
                "field_key": "N/A",
                "wire_key": "N/A",
                "offset_basis": "N/A",
                "object_offset": "N/A",
                "storage_width": "N/A",
                "wire_len": "0",
                "corrected_order": "N/A",
                "tag": prior["new_tag"],
                "corrected_gate": "N/A",
                "semantic_name": "control_flow_or_container_helper",
                "structural_status": "NOT_WIRE",
                "semantic_status": "NOT_WIRE",
                "field_source_va": "N/A",
                "field_source_file_offset": "N/A",
                "wire_call_va": "N/A",
                "wire_call_file_offset": "N/A",
                "persistent_write_va": "N/A",
                "consumer_va": "N/A",
                "codec_span_start": fmt_va(codec_start),
                "codec_span_end": fmt_va(codec_end),
                "codec_span_sha256": codec_hash,
                "support_span_sha256": support_hashes,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "blocker": "",
                "required_next_evidence": "",
                "image_sha256": image.sha256,
            }
        )

    field_rows: list[dict[str, str]] = []
    for spec in CSKILL_FIELD_SPECS:
        (
            base_key, direction, order, field_key, wire_key, offset_basis,
            object_offset, storage_width, wire_len, tag, gate, semantic_name,
            source_va, wire_call_va, persistent_write_va, consumer_va,
        ) = spec
        if semantic_name in {"skill_id_u16_wire", "current_skill_level_u16"}:
            semantic_span = (
                0x004328C2, 0x00432A1A,
                "48d6d72bcbe3c0e62750eae148d226129616f5a7f1b952f541f879c9009a4b98",
            )
            semantic_consumer = "0x004328C2;0x007523D0;0x00752C00;0x00755681;0x0075588B"
        elif semantic_name == "current_level_skill_point_progress_u32":
            semantic_span = (
                0x00754280, 0x0075432E,
                "c5734671cb2f3941d26840e898fef8f1c210405c30eb255de257aa9254d76c5b",
            )
            semantic_consumer = "0x00754280;0x00752440;0x00752C00;0x00755681;0x0075588B"
        else:
            semantic_span = (codec_start, codec_end, codec_hash)
            semantic_consumer = consumer_va
        prior = by_key[base_key]
        base_ref = "PF_A2_SERIALIZER_SLOT34_DELTA.tsv|%s" % base_key
        correction_key = stable_key(
            "A2_CSKILL_CORRECTION",
            base_ref,
            "CORRECT_FIELD_LAYOUT",
            field_key,
            wire_key,
            codec_hash,
        )
        evidence_key = stable_key(
            "IMAGE",
            image.sha256,
            field_key,
            wire_key,
            source_va,
            wire_call_va,
            persistent_write_va,
            consumer_va,
            codec_hash,
            support_hashes,
        )
        corrections.append(
            {
                "correction_key": correction_key,
                "conflict_key": stable_key("ATTR_CONFLICT", correction_key),
                "base_row_ref": base_ref,
                "direction": direction,
                "delta_action": "CORRECT_FIELD_LAYOUT",
                "prior_order": prior["new_order"],
                "prior_tag": prior["new_tag"],
                "prior_field_offset": prior["new_field_offset"],
                "prior_gate": prior["new_gate_condition"],
                "field_key": field_key,
                "wire_key": wire_key,
                "offset_basis": offset_basis,
                "object_offset": object_offset,
                "storage_width": storage_width,
                "wire_len": wire_len,
                "corrected_order": str(order),
                "tag": tag,
                "corrected_gate": gate,
                "semantic_name": semantic_name,
                "structural_status": "PROVEN_EXACT",
                "semantic_status": "PROVEN_EXACT",
                "field_source_va": fmt_va(source_va),
                "field_source_file_offset": fmt_off(image.va_to_off(source_va)),
                "wire_call_va": fmt_va(wire_call_va),
                "wire_call_file_offset": fmt_off(image.va_to_off(wire_call_va)),
                "persistent_write_va": fmt_va(persistent_write_va),
                "consumer_va": consumer_va,
                "codec_span_start": fmt_va(codec_start),
                "codec_span_end": fmt_va(codec_end),
                "codec_span_sha256": codec_hash,
                "support_span_sha256": support_hashes,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "blocker": "",
                "required_next_evidence": "",
                "image_sha256": image.sha256,
            }
        )
        field_rows.append(
            {
                "field_key": field_key,
                "wire_key": wire_key,
                "class": "CSkillAttr",
                "parent_chain": "Attribute>DBAttribute>CSkillAttr",
                "direction": direction,
                "offset_basis": offset_basis,
                "storage_width": storage_width,
                "order": str(order),
                "mask_bit": "ALWAYS",
                "gate": gate,
                "offset": object_offset,
                "tag": tag,
                "len": wire_len,
                "structural_type": semantic_name,
                "structural_status": "PROVEN_EXACT",
                "default_value": (
                    "0" if field_key == "CSkillAttr@0x48.2#W"
                    else "N/A" if field_key == "N/A"
                    else "ABSENT_UNTIL_INSERT"
                ),
                "default_writer_va": "0x004B8DF7" if field_key == "CSkillAttr@0x48.2#W" else "N/A",
                "semantic_name": semantic_name,
                "semantic_status": "PROVEN_EXACT",
                "semantic_source_load_va": "N/A",
                "semantic_producer_va": fmt_va(persistent_write_va),
                "semantic_consumer_va": semantic_consumer,
                "semantic_evidence_span_start": fmt_va(semantic_span[0]),
                "semantic_evidence_span_end": fmt_va(semantic_span[1]),
                "semantic_evidence_span_sha256": semantic_span[2],
                "semantic_support_spans": support_hashes,
                "producer_va": (
                    "0x004B8DF7;0x00751E3E;0x007521DF"
                    if field_key == "CSkillAttr@0x48.2#W"
                    else fmt_va(persistent_write_va)
                ),
                "consumer_va": consumer_va if consumer_va != "" else "UNKNOWN",
                "consumer_slot": "N/A",
                "codec_slot": "+0x34",
                "write_site_va": fmt_va(source_va) if direction == "W" else "N/A",
                "read_site_va": fmt_va(source_va) if direction == "R" else "N/A",
                "file_offset": fmt_off(image.va_to_off(source_va)),
                "span_start": fmt_va(codec_start),
                "span_end": fmt_va(codec_end),
                "span_sha256": codec_hash,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "conflicts_with": "",
                "blocker": "",
                "required_next_evidence": "",
                "image_sha256": image.sha256,
            }
        )

    corrections.sort(key=lambda row: (row["delta_action"], row["base_row_ref"]))
    field_rows.sort(key=lambda row: (row["direction"], int(row["order"])))
    if (
        len(corrections) != 28
        or len(field_rows) != 8
        or len({row["correction_key"] for row in corrections}) != 28
        or len({row["evidence_key"] for row in corrections}) != 28
        or len({row["wire_key"] for row in field_rows}) != 8
        or Counter(row["semantic_status"] for row in field_rows)
        != Counter({"PROVEN_EXACT": 8})
    ):
        raise SystemExit("cskill_correction_census_or_duplicate_mismatch")
    return corrections, field_rows


