    for start, end, expected, label in support_spans:
        if image.span_hash(start, end) != expected:
            raise SystemExit("cooldown_support_span_hash_mismatch_%s" % label)
    if _sha256_path(BASE_SLOT34_A2_PATH) != "1778728a2d4ec53562a51ea0361bca530942f48d0f49af18b295f1ff6a49c334":
        raise SystemExit("cooldown_frozen_slot34_base_hash_mismatch")
    with BASE_SLOT34_A2_PATH.open("r", encoding="utf-8", newline="") as handle:
        base_rows = list(csv.DictReader(handle, delimiter="\t"))
    by_key = {row["delta_key"]: row for row in base_rows}
    expected_keys = set(COOLDOWN_REMOVE_KEYS) | {spec[0] for spec in COOLDOWN_FIELD_SPECS}
    if (
        len(expected_keys) != 22
        or any(
            key not in by_key or by_key[key].get("message") != "CCooldownAttr"
            for key in expected_keys
        )
    ):
        raise SystemExit("cooldown_frozen_row_key_census_mismatch")

    support_hashes = ";".join(span[2] for span in support_spans)
    support_text = ";".join(
        "%s=%s..%s@%s" % (label, fmt_va(start), fmt_va(end), expected)
        for start, end, expected, label in support_spans
    )
    corrections: list[dict[str, str]] = []
    for base_key in COOLDOWN_REMOVE_KEYS:
        prior = by_key[base_key]
        base_ref = "PF_A2_SERIALIZER_SLOT34_DELTA.tsv|%s" % base_key
        correction_key = stable_key(
            "A2_COOLDOWN_CORRECTION", base_ref,
            "REMOVE_NON_WIRE_CONTROL_FLOW_ROW", codec_hash,
        )
        evidence_key = stable_key(
            "IMAGE", image.sha256, base_ref, "NOT_WIRE", codec_hash, support_hashes
        )
        corrections.append(
            {
                "correction_key": correction_key,
                "conflict_key": stable_key("ATTR_CONFLICT", correction_key),
                "base_row_ref": base_ref,
                "direction": prior["direction(W/R)"],
                "delta_action": "REMOVE_NON_WIRE_CONTROL_FLOW_ROW",
                "prior_order": prior["new_order"],
                "prior_tag": prior["new_tag"],
                "prior_field_offset": prior["new_field_offset"],
                "prior_gate": prior["new_gate_condition"],
                "field_key": "N/A",
                "wire_key": "N/A",
                "offset_basis": "N/A",
                "object_offset": "N/A",
                "storage_width": "N/A",
                "wire_len": "0",
                "corrected_order": "N/A",
                "tag": prior["new_tag"],
                "corrected_gate": "N/A",
                "semantic_name": "control_flow_iterator_guard_or_container_helper",
                "structural_status": "NOT_WIRE",
                "semantic_status": "NOT_WIRE",
                "field_source_va": "N/A",
                "field_source_file_offset": "N/A",
                "wire_call_va": "N/A",
                "wire_call_file_offset": "N/A",
                "persistent_write_va": "N/A",
                "consumer_va": "N/A",
                "codec_span_start": fmt_va(codec_start),
                "codec_span_end": fmt_va(codec_end),
                "codec_span_sha256": codec_hash,
                "support_span_sha256": support_hashes,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "blocker": "",
                "required_next_evidence": "",
                "image_sha256": image.sha256,
            }
        )

    field_rows: list[dict[str, str]] = []
    for spec in COOLDOWN_FIELD_SPECS:
        (
            base_key, direction, order, field_key, wire_key, offset_basis,
            object_offset, storage_width, wire_len, tag, gate, semantic_name,
            semantic_status, source_va, wire_call_va, persistent_write_va,
            consumer_va,
        ) = spec
        prior = by_key[base_key]
        base_ref = "PF_A2_SERIALIZER_SLOT34_DELTA.tsv|%s" % base_key
        correction_key = stable_key(
            "A2_COOLDOWN_CORRECTION", base_ref, "CORRECT_FIELD_LAYOUT",
            field_key, wire_key, codec_hash,
        )
        evidence_key = stable_key(
            "IMAGE", image.sha256, field_key, wire_key, source_va,
            wire_call_va, persistent_write_va, consumer_va, semantic_name,
            semantic_status, codec_hash, support_hashes,
        )
        if semantic_status == "PROVEN_EXACT":
            blocker = required = ""
        else:
            blocker = "the signed cooldown selector role is exact, but its skill/action/item namespace is not proved"
            required = "a named selector producer/consumer or varied CAPTURE evidence retained as a separate source"
        corrections.append(
            {
                "correction_key": correction_key,
                "conflict_key": stable_key("ATTR_CONFLICT", correction_key),
                "base_row_ref": base_ref,
                "direction": direction,
                "delta_action": "CORRECT_FIELD_LAYOUT",
                "prior_order": prior["new_order"],
                "prior_tag": prior["new_tag"],
                "prior_field_offset": prior["new_field_offset"],
                "prior_gate": prior["new_gate_condition"],
                "field_key": field_key,
                "wire_key": wire_key,
                "offset_basis": offset_basis,
                "object_offset": object_offset,
                "storage_width": storage_width,
                "wire_len": wire_len,
                "corrected_order": str(order),
                "tag": tag,
                "corrected_gate": gate,
                "semantic_name": semantic_name,
                "structural_status": "PROVEN_EXACT",
                "semantic_status": semantic_status,
                "field_source_va": fmt_va(source_va),
                "field_source_file_offset": fmt_off(image.va_to_off(source_va)),
                "wire_call_va": fmt_va(wire_call_va),
                "wire_call_file_offset": fmt_off(image.va_to_off(wire_call_va)),
                "persistent_write_va": fmt_va(persistent_write_va),
                "consumer_va": consumer_va,
                "codec_span_start": fmt_va(codec_start),
                "codec_span_end": fmt_va(codec_end),
                "codec_span_sha256": codec_hash,
                "support_span_sha256": support_hashes,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "blocker": blocker,
                "required_next_evidence": required,
                "image_sha256": image.sha256,
            }
        )
        count_write = field_key == "CCooldownAttr@0x48.2#W"
        semantic_span = (
            (codec_start, codec_end, codec_hash)
            if "entry_count" in semantic_name
            else support_spans[6][:3]
            if semantic_name == "cooldown_selector_s16"
            else support_spans[7][:3]
        )
        field_rows.append(
            {
                "field_key": field_key,
                "wire_key": wire_key,
                "class": "CCooldownAttr",
                "parent_chain": "PcRefObject>Attribute>DBAttribute>CCooldownAttr",
                "direction": direction,
                "offset_basis": offset_basis,
                "storage_width": storage_width,
                "order": str(order),
                "mask_bit": "ALWAYS",
                "gate": gate,
                "offset": object_offset,
                "tag": tag,
                "len": wire_len,
                "structural_type": semantic_name,
                "structural_status": "PROVEN_EXACT",
                "default_value": "0" if count_write else "N/A" if field_key == "N/A" else "ABSENT_UNTIL_INSERT",
                "default_writer_va": "0x0058CD77" if count_write else "N/A",
                "semantic_name": semantic_name,
                "semantic_status": semantic_status,
                "semantic_source_load_va": fmt_va(source_va),
                "semantic_producer_va": fmt_va(persistent_write_va),
                "semantic_consumer_va": consumer_va,
                "semantic_evidence_span_start": fmt_va(semantic_span[0]),
                "semantic_evidence_span_end": fmt_va(semantic_span[1]),
                "semantic_evidence_span_sha256": semantic_span[2],
                "semantic_support_spans": support_text,
                "producer_va": fmt_va(persistent_write_va),
                "consumer_va": consumer_va,
                "consumer_slot": "N/A",
                "codec_slot": "+0x34",
                "write_site_va": fmt_va(source_va) if direction == "W" else "N/A",
                "read_site_va": fmt_va(source_va) if direction == "R" else "N/A",
                "file_offset": fmt_off(image.va_to_off(source_va)),
                "span_start": fmt_va(codec_start),
                "span_end": fmt_va(codec_end),
                "span_sha256": codec_hash,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "conflicts_with": "",
                "blocker": blocker,
                "required_next_evidence": required,
                "image_sha256": image.sha256,
            }
        )

    corrections.sort(key=lambda row: (row["delta_action"], row["base_row_ref"]))
    field_rows.sort(key=lambda row: (int(row["order"]), row["direction"]))
    if (
        len(corrections) != 22
        or len(field_rows) != 6
        or len({row["correction_key"] for row in corrections}) != 22
        or len({row["evidence_key"] for row in corrections}) != 22
        or len({row["wire_key"] for row in field_rows}) != 6
        or Counter(row["semantic_status"] for row in field_rows)
        != Counter({"PROVEN_EXACT": 4, "PROVEN_ROLE_ONLY": 2})
    ):
        raise SystemExit("cooldown_correction_census_or_duplicate_mismatch")
    return corrections, field_rows


