def build_express_count_field_semantics(image: Image) -> list[dict[str, str]]:
    codec_start, codec_end = 0x006E3990, 0x006E39EA
    codec_hash = "73555f11e198330d49e4c0f8f835eaa92b931c34066bbed268d17f04c86f25e9"
    support_spans = (
        (0x006E3720, 0x006E373F, "94734ebd489ee581d5fb4d49f8e04afd70b4db4bbeccc7e408bd73d98b773320", "constructor"),
        (0x006E3760, 0x006E37A0, "59ae7c3e9ce28816f90a46290bd64c771c5e8997e3aa7da9d55f17c6100e7600", "copy"),
        (0x006E39F0, 0x006E3A3A, "ed484799effc59e4e8a78df0faa6caa912f66e18c10ab59dc8b9dff22739cf74", "delta_compare_mask_producer"),
        (0x006E3A40, 0x006E3A88, "e980be072bc55bfa82960bb21c3912d66149201b72b54d34a48f7e02ec30fb83", "fill_absent_field"),
    )
    if image.span_hash(codec_start, codec_end) != codec_hash:
        raise SystemExit("express_count_codec_span_hash_mismatch")
    for start, end, expected, label in support_spans:
        if image.span_hash(start, end) != expected:
            raise SystemExit("express_count_support_span_hash_mismatch_%s" % label)
    _assert_bytes(image, 0x006E3730, "c64628ff", "express_count_mask_default")
    _assert_bytes(image, 0x006E3734, "884629", "express_count_value_default")

    if _sha256_path(BASE_SLOT34_A2_PATH) != "1778728a2d4ec53562a51ea0361bca530942f48d0f49af18b295f1ff6a49c334":
        raise SystemExit("express_count_frozen_slot34_base_hash_mismatch")
    with BASE_SLOT34_A2_PATH.open("r", encoding="utf-8", newline="") as handle:
        base_rows = list(csv.DictReader(handle, delimiter="\t"))
    by_key = {row["delta_key"]: row for row in base_rows}
    for spec in EXPRESS_COUNT_FIELD_SPECS:
        base_key, direction, order, _field_key, _wire_key, offset, *_tail = spec
        prior = by_key.get(base_key)
        if (
            prior is None
            or prior.get("message") != "ExpressCountAttr"
            or prior.get("action") != "ADD_CORRECTED_SLOT34_ROW"
            or prior.get("direction(W/R)") != direction
            or prior.get("new_order") != str(order)
            or prior.get("new_field_offset", "").upper() != ("+" + offset).upper()
            or prior.get("new_tag") != "0x0B"
            or prior.get("new_len") != "1"
        ):
            raise SystemExit("express_count_frozen_direct_row_mismatch_%s" % base_key)

    support_text = ";".join(
        "%s=%s..%s@%s" % (label, fmt_va(start), fmt_va(end), expected)
        for start, end, expected, label in support_spans
    )
    support_hashes = ";".join(span[2] for span in support_spans)
    rows: list[dict[str, str]] = []
    for spec in EXPRESS_COUNT_FIELD_SPECS:
        (
            base_key, direction, order, field_key, wire_key, offset, gate,
            structural_type, semantic_name, semantic_status, transfer_va,
        ) = spec
        is_mask = offset == "0x28"
        blocker = (
            "the byte is the sole ExpressCountAttr count value, but IMAGE does not prove whether it means used, sent, or remaining count, nor its reset window"
            if not is_mask else ""
        )
        required = (
            "a named original-client producer/consumer or varied CAPTURE evidence retained as a separate source"
            if not is_mask else ""
        )
        semantic_span = (
            support_spans[2][:3] if is_mask else (codec_start, codec_end, codec_hash)
        )
        semantic_producer_va = 0x006E39F0 if is_mask else 0x006E3734
        semantic_consumer_va = 0x006E39BF
        evidence_key = stable_key(
            "IMAGE", image.sha256, "ExpressCountAttr", base_key, field_key,
            wire_key, direction, order, offset, gate, structural_type,
            semantic_name, semantic_status, transfer_va, codec_hash,
            support_hashes,
        )
        rows.append(
            {
                "field_key": field_key,
                "wire_key": wire_key,
                "class": "ExpressCountAttr",
                "parent_chain": "PcRefObject>Attribute>DBAttribute>ExpressCountAttr",
                "direction": direction,
                "offset_basis": "OBJECT",
                "storage_width": "1",
                "order": str(order),
                "mask_bit": "ALWAYS" if is_mask else "0x01",
                "gate": gate,
                "offset": offset,
                "tag": "0x0B",
                "len": "1",
                "structural_type": structural_type,
                "structural_status": "PROVEN_EXACT",
                "default_value": "0xFF" if is_mask else "0",
                "default_writer_va": "0x006E3730" if is_mask else "0x006E3734",
                "semantic_name": semantic_name,
                "semantic_status": semantic_status,
                "semantic_source_load_va": fmt_va(transfer_va),
                "semantic_producer_va": fmt_va(semantic_producer_va),
                "semantic_consumer_va": fmt_va(semantic_consumer_va),
                "semantic_evidence_span_start": fmt_va(semantic_span[0]),
                "semantic_evidence_span_end": fmt_va(semantic_span[1]),
                "semantic_evidence_span_sha256": semantic_span[2],
                "semantic_support_spans": support_text,
                "producer_va": fmt_va(semantic_producer_va),
                "consumer_va": fmt_va(semantic_consumer_va),
                "consumer_slot": "N/A",
                "codec_slot": "+0x34",
                "write_site_va": fmt_va(transfer_va) if direction == "W" else "N/A",
                "read_site_va": fmt_va(transfer_va) if direction == "R" else "N/A",
                "file_offset": fmt_off(image.va_to_off(transfer_va)),
                "span_start": fmt_va(codec_start),
                "span_end": fmt_va(codec_end),
                "span_sha256": codec_hash,
                "evidence_key": evidence_key,
                "source": "IMAGE",
                "conflicts_with": "",
                "blocker": blocker,
                "required_next_evidence": required,
                "image_sha256": image.sha256,
            }
        )

    rows.sort(key=lambda row: (int(row["order"]), row["direction"]))
    if (
        len(rows) != 4
        or len({row["field_key"] for row in rows}) != 4
        or len({row["wire_key"] for row in rows}) != 4
        or len({row["evidence_key"] for row in rows}) != 4
        or Counter(row["semantic_status"] for row in rows)
        != Counter({"PROVEN_EXACT": 2, "PROVEN_ROLE_ONLY": 2})
    ):
        raise SystemExit("express_count_field_census_or_duplicate_mismatch")
    return rows


