def build_itembag_codec_corrections(
    image: Image,
) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    common_start, common_end = 0x0046F180, 0x0046F3E9
    common_hash = image.span_hash(common_start, common_end)
    if common_hash != "29e38267ab54c852e3f1338c2fb833e3b9d1a41903544a390489c264c09fa813":
        raise SystemExit("itembag_common_codec_span_hash_mismatch")
    support_spans = (
        (0x0046F3F0, 0x0046F469, "de13f1abba13b83ca153793431e5ffb549f81104d5d313e499446d8d22c9cb91"),
        (0x0066A9D0, 0x0066AA53, "9ac82efeeee14f5b87a1eacaebdd5ac53579adf32795fd64e524d840575a63c7"),
        (0x0046EA70, 0x0046EAF3, "f8c41a240e978a3d29f7071bf0c939aed9ab1451d77192277faefa231187c260"),
        (0x00469FA0, 0x00469FD8, "828554cb9ece35a2316ffc9e8bf44be3b2ef033bd189cb9b15400ecd3b48c63f"),
        (0x00471830, 0x00471910, "0756593899a697399b4cbdc8f03f32928f1829c20ebcc9cbcd34b8254c0a0692"),
    )
    for start, end, expected in support_spans:
        if image.span_hash(start, end) != expected:
            raise SystemExit("itembag_support_span_hash_mismatch_0x%08X" % start)
    for va, expected_hex, label in (
        (0x0046F41A, "e83182ffff", "dbattribute_ctor_call"),
        (0x0046F434, "c706b8ecf000", "itembag_vtable_store"),
        (0x0046F43A, "e891b51f00", "primary_container_ctor_call"),
        (0x0046F451, "e81af6ffff", "secondary_container_ctor_call"),
        (0x0066AA37, "c7461c00000000", "primary_stored_size_zero"),
        (0x0046EAD7, "c7461c00000000", "secondary_stored_size_zero"),
        (0x0046F1C5, "0fb74f44", "primary_count_write_load"),
        (0x0046F1D6, "e825b44200", "primary_count_write_call"),
        (0x0046F250, "ffd0", "primary_entry_write_slot34_call"),
        (0x0046F269, "0fb74f64", "secondary_count_write_load"),
        (0x0046F27C, "e87fb34200", "secondary_count_write_call"),
        (0x0046F2CE, "83c010", "secondary_qword_write_node_offset"),
        (0x0046F2D6, "e825b34200", "secondary_qword_write_call"),
        (0x0046F2FD, "e83eb34200", "primary_count_read_call"),
        (0x0046F33F, "ffd2", "primary_entry_read_slot34_call"),
        (0x0046F35B, "e8c0f8ffff", "primary_entry_insert_call"),
        (0x0046F388, "e8b3b24200", "secondary_count_read_call"),
        (0x0046F3B5, "e886b24200", "secondary_qword_read_call"),
        (0x0046F3C6, "e805efffff", "secondary_qword_insert_call"),
        (0x00469FAF, "e8cc510000", "byte_wrapper_common_call"),
        (0x00469FC2, "e839064300", "byte_wrapper_write_call"),
        (0x00469FCD, "e86e064300", "byte_wrapper_read_call"),
        (0x00471842, "e839d9ffff", "u16_wrapper_common_call"),
        (0x00471858, "e8a38d4200", "u16_wrapper_write_call"),
        (0x0047186F, "e8cc8d4200", "u16_wrapper_read_call"),
    ):
        _assert_bytes(image, va, expected_hex, label)

    base_hash = _sha256_path(BASE_SLOT34_A2_PATH)
    if base_hash != "1778728a2d4ec53562a51ea0361bca530942f48d0f49af18b295f1ff6a49c334":
        raise SystemExit("frozen_slot34_base_hash_mismatch")
    with BASE_SLOT34_A2_PATH.open("r", encoding="utf-8", newline="") as handle:
        base_rows = list(csv.DictReader(handle, delimiter="\t"))

    common_actual = {
        ("W", "0x0006E5D6"): ("PRIMARY_COUNT", 0x0046F1C5, 0x0046F1D6),
        ("W", "0x0006E650"): ("PRIMARY_ENTRY", 0x0046F250, 0x0046F250),
        ("W", "0x0006E67C"): ("SECONDARY_COUNT", 0x0046F269, 0x0046F27C),
        ("W", "0x0006E6D6"): ("SECONDARY_QWORD", 0x0046F2CE, 0x0046F2D6),
        ("R", "0x0006E6FD"): ("PRIMARY_COUNT", 0x0046F2FD, 0x0046F2FD),
        ("R", "0x0006E73F"): ("PRIMARY_ENTRY", 0x0046F33F, 0x0046F33F),
        ("R", "0x0006E788"): ("SECONDARY_COUNT", 0x0046F388, 0x0046F388),
        ("R", "0x0006E7B5"): ("SECONDARY_QWORD", 0x0046F3B5, 0x0046F3B5),
    }
    support_hashes = ";".join(item[2] for item in support_spans)
    corrections: list[dict[str, str]] = []
    field_rows: list[dict[str, str]] = []

    def append_correction(
        class_name: str,
        prior: dict[str, str],
        action: str,
        field_key: str,
        wire_key: str,
        offset_basis: str,
        object_offset: str,
        storage_width: str,
        wire_len: str,
        corrected_order: str,
        tag: str,
        gate: str,
        semantic_name: str,
        structural_status: str,
        semantic_status: str,
        source_va: int | None,
        wire_call_va: int | None,
        persistent_write_va: int | None,
        consumer_va: str,
        codec_start: int,
        codec_end: int,
        codec_hash: str,
    ) -> dict[str, str]:
        base_ref = "PF_A2_SERIALIZER_SLOT34_DELTA.tsv|%s" % prior["delta_key"]
        correction_key = stable_key(
            "A2_ITEMBAG_CORRECTION", class_name, base_ref, action,
            field_key, wire_key, codec_hash,
        )
        evidence_key = stable_key(
            "IMAGE", image.sha256, class_name, base_ref, action,
            field_key, wire_key, source_va, wire_call_va,
            persistent_write_va, consumer_va, codec_hash, support_hashes,
        )
        row = {
            "correction_key": correction_key,
            "conflict_key": stable_key("ATTR_CONFLICT", correction_key),
            "class": class_name,
            "base_row_ref": base_ref,
            "direction": prior["direction(W/R)"],
            "delta_action": action,
            "prior_order": prior["new_order"],
            "prior_tag": prior["new_tag"],
            "prior_field_offset": prior["new_field_offset"],
            "prior_gate": prior["new_gate_condition"],
            "field_key": field_key,
            "wire_key": wire_key,
            "offset_basis": offset_basis,
            "object_offset": object_offset,
            "storage_width": storage_width,
            "wire_len": wire_len,
            "corrected_order": corrected_order,
            "tag": tag,
            "corrected_gate": gate,
            "semantic_name": semantic_name,
            "structural_status": structural_status,
            "semantic_status": semantic_status,
            "field_source_va": fmt_va(source_va),
            "field_source_file_offset": fmt_off(image.va_to_off(source_va)) if source_va else "N/A",
            "wire_call_va": fmt_va(wire_call_va),
            "wire_call_file_offset": fmt_off(image.va_to_off(wire_call_va)) if wire_call_va else "N/A",
            "persistent_write_va": fmt_va(persistent_write_va),
            "consumer_va": consumer_va,
            "codec_span_start": fmt_va(codec_start),
            "codec_span_end": fmt_va(codec_end),
            "codec_span_sha256": codec_hash,
            "support_span_sha256": support_hashes,
            "evidence_key": evidence_key,
            "source": "IMAGE",
            "blocker": "" if semantic_status == "NOT_WIRE" else "gameplay identity is not uniquely bound to Data or an exact UI slot",
            "required_next_evidence": "" if semantic_status == "NOT_WIRE" else "unique Data/UI consumer or varied CAPTURE evidence as a separate source",
            "image_sha256": image.sha256,
        }
        corrections.append(row)
        return row

    for (
        class_name, family, parent_chain, wrapper_offset, wrapper_len, wrapper_tag,
        wrapper_w_source, wrapper_w_call, wrapper_r_source, wrapper_r_call,
        wrapper_span,
    ) in ITEMBAG_CLASS_SPECS:
        class_rows = [row for row in base_rows if row.get("message") == class_name]
        expected_total = (
            50 if family == "DIRECT"
            else 54 if family in {"BYTE_WRAPPER", "INHERITED_BYTE_WRAPPER"}
            else 68
        )
        if len(class_rows) != expected_total:
            raise SystemExit("itembag_frozen_class_census_mismatch_%s" % class_name)
        common_rows = [
            row for row in class_rows
            if row.get("direction(W/R)") in {"W", "R"}
            and row.get("new_file_off_claim") in ITEMBAG_COMMON_FILE_OFFSETS
        ]
        if len(common_rows) != 42:
            raise SystemExit("itembag_common_frozen_row_census_mismatch_%s" % class_name)
        base_order = 4 if family == "DIRECT" else 5
        seen_actual = set()
        for prior in common_rows:
            lookup = (prior["direction(W/R)"], prior["new_file_off_claim"])
            actual = common_actual.get(lookup)
            if actual is None:
                append_correction(
                    class_name, prior, "REMOVE_NON_WIRE_CONTROL_FLOW_ROW",
                    "N/A", "N/A", "N/A", "N/A", "N/A", "0", "N/A",
                    prior["new_tag"], "N/A", "control_flow_or_container_helper",
                    "NOT_WIRE", "NOT_WIRE", None, None, None, "N/A",
                    common_start, common_end, common_hash,
                )
                continue
            seen_actual.add(lookup)
            kind, source_va, wire_call_va = actual
            direction = prior["direction(W/R)"]
            order_index = {
                "PRIMARY_COUNT": 0,
                "PRIMARY_ENTRY": 1,
                "SECONDARY_COUNT": 2,
                "SECONDARY_QWORD": 3,
            }[kind]
            order = base_order + order_index
            if kind == "PRIMARY_COUNT":
                field_key = "%s@0x44.2#W" % class_name if direction == "W" else "N/A"
                wire_key = field_key if direction == "W" else "%s.primary_count#R" % class_name
                basis = "OBJECT" if direction == "W" else "WIRE_CONTROL"
                offset = "0x44" if direction == "W" else "N/A"
                storage = "4" if direction == "W" else "N/A"
                tag, wire_len = "0x0F", "2"
                semantic = "primary_container_count"
                persistent, consumer = (None, "0x0046F1DB") if direction == "W" else (None, "0x0046F304;0x0046F370")
            elif kind == "PRIMARY_ENTRY":
                field_key = "N/A"
                wire_key = "%s.primary_entry.slot34#%s" % (class_name, direction)
                basis, offset, storage = "DYNAMIC_OBJECT", "N/A", "DYNAMIC"
                tag, wire_len = "SUBCALL:DYNAMIC+0x34", "DYNAMIC"
                semantic = "primary_polymorphic_attr_entry"
                persistent, consumer = (0x0046F35B, "0x0046EC20") if direction == "R" else (None, "dynamic entry slot +0x34")
            elif kind == "SECONDARY_COUNT":
                field_key = "%s@0x64.2#W" % class_name if direction == "W" else "N/A"
                wire_key = field_key if direction == "W" else "%s.secondary_count#R" % class_name
                basis = "OBJECT" if direction == "W" else "WIRE_CONTROL"
                offset = "0x64" if direction == "W" else "N/A"
                storage = "4" if direction == "W" else "N/A"
                tag, wire_len = "0x0F", "2"
                semantic = "secondary_container_count"
                persistent, consumer = (None, "0x0046F281") if direction == "W" else (None, "0x0046F38D;0x0046F3CC")
            else:
                field_key = "%s.SecondaryNode@0x10.8#%s" % (class_name, direction)
                wire_key = field_key
                basis, offset, storage = "RECORD_NODE", "0x10", "8"
                tag, wire_len = "0x32", "8"
                semantic = "secondary_node_payload_qword"
                persistent, consumer = (0x0046F3C6, "0x0046E2D0") if direction == "R" else (None, "0x0046E2D0")
            correction = append_correction(
                class_name, prior, "CORRECT_FIELD_LAYOUT", field_key, wire_key,
                basis, offset, storage, wire_len, str(order), tag, "ALWAYS",
                semantic, "PROVEN_EXACT", "PROVEN_ROLE_ONLY", source_va,
                wire_call_va, persistent, consumer, common_start, common_end,
                common_hash,
            )
            field_rows.append(
                {
                    "field_key": field_key,
                    "wire_key": wire_key,
                    "class": class_name,
                    "parent_chain": parent_chain,
                    "direction": direction,
                    "offset_basis": basis,
                    "storage_width": storage,
                    "order": str(order),
                    "mask_bit": "ALWAYS",
                    "gate": "ALWAYS",
                    "offset": offset,
                    "tag": tag,
                    "len": wire_len,
                    "structural_type": semantic,
                    "structural_status": "PROVEN_EXACT",
                    "default_value": "0" if direction == "W" and kind in {"PRIMARY_COUNT", "SECONDARY_COUNT"} else "N/A",
                    "default_writer_va": (
                        "0x0066AA37" if direction == "W" and kind == "PRIMARY_COUNT"
                        else "0x0046EAD7" if direction == "W" and kind == "SECONDARY_COUNT"
                        else "N/A"
                    ),
                    "semantic_name": semantic,
                    "semantic_status": "PROVEN_ROLE_ONLY",
                    "semantic_source_load_va": fmt_va(source_va),
                    "semantic_producer_va": fmt_va(persistent),
                    "semantic_consumer_va": consumer,
                    "semantic_evidence_span_start": fmt_va(common_start),
                    "semantic_evidence_span_end": fmt_va(common_end),
                    "semantic_evidence_span_sha256": common_hash,
                    "semantic_support_spans": support_hashes,
                    "producer_va": fmt_va(persistent),
                    "consumer_va": consumer,
                    "consumer_slot": "+0x34" if kind == "PRIMARY_ENTRY" else "N/A",
                    "codec_slot": "+0x34",
                    "write_site_va": fmt_va(source_va) if direction == "W" else "N/A",
                    "read_site_va": fmt_va(source_va) if direction == "R" else "N/A",
                    "file_offset": fmt_off(image.va_to_off(source_va)),
                    "span_start": fmt_va(common_start),
                    "span_end": fmt_va(common_end),
                    "span_sha256": common_hash,
                    "evidence_key": correction["evidence_key"],
                    "source": "IMAGE",
                    "conflicts_with": "",
                    "blocker": correction["blocker"],
                    "required_next_evidence": correction["required_next_evidence"],
                    "image_sha256": image.sha256,
                }
            )
        if seen_actual != set(common_actual):
            raise SystemExit("itembag_actual_frozen_row_census_mismatch_%s" % class_name)

        if wrapper_offset is not None:
            wrapper_hash = image.span_hash(*wrapper_span)
            own_offs = {
                "W": fmt_off(image.va_to_off(wrapper_w_call)),
                "R": fmt_off(image.va_to_off(wrapper_r_call)),
            }
            own_rows = [
                row for row in class_rows
                if row.get("direction(W/R)") in {"W", "R"}
                and row.get("new_file_off_claim") == own_offs[row["direction(W/R)"]]
            ]
            if len(own_rows) != 2:
                raise SystemExit("itembag_wrapper_field_frozen_row_census_mismatch_%s" % class_name)
            for prior in own_rows:
                direction = prior["direction(W/R)"]
                source_va = wrapper_w_source if direction == "W" else wrapper_r_source
                wire_call_va = wrapper_w_call if direction == "W" else wrapper_r_call
                if family == "INHERITED_BYTE_WRAPPER":
                    inherited_key = "BackpackAttr@0x%X.%d#%s" % (
                        wrapper_offset, wrapper_len, direction,
                    )
                    append_correction(
                        class_name, prior, "ANNOTATE_INHERITED_FIELD_ALIAS",
                        inherited_key, inherited_key, "INHERITED_BASE",
                        "BackpackAttr+0x%X" % wrapper_offset,
                        str(wrapper_len), str(wrapper_len), "9", wrapper_tag,
                        "ALWAYS", "inherited_BackpackAttr_wrapper_byte_field",
                        "PROVEN_EXACT", "PROVEN_ROLE_ONLY", source_va,
                        wire_call_va, None, "BackpackAttr codec ownership",
                        wrapper_span[0], wrapper_span[1], wrapper_hash,
                    )
                    continue
                field_key = "%s@0x%X.%d#%s" % (
                    class_name, wrapper_offset, wrapper_len, direction,
                )
                semantic = "wrapper_byte_field" if wrapper_len == 1 else "wrapper_u16_field"
                correction = append_correction(
                    class_name, prior, "CORRECT_FIELD_LAYOUT", field_key,
                    field_key, "OBJECT", "0x%X" % wrapper_offset,
                    str(wrapper_len), str(wrapper_len), "9", wrapper_tag, "ALWAYS",
                    semantic, "PROVEN_EXACT", "PARTIAL", source_va, wire_call_va,
                    None, "UNKNOWN", wrapper_span[0], wrapper_span[1], wrapper_hash,
                )
                field_rows.append(
                    {
                        "field_key": field_key,
                        "wire_key": field_key,
                        "class": class_name,
                        "parent_chain": parent_chain,
                        "direction": direction,
                        "offset_basis": "OBJECT",
                        "storage_width": str(wrapper_len),
                        "order": "9",
                        "mask_bit": "ALWAYS",
                        "gate": "ALWAYS",
                        "offset": "0x%X" % wrapper_offset,
                        "tag": wrapper_tag,
                        "len": str(wrapper_len),
                        "structural_type": semantic,
                        "structural_status": "PROVEN_EXACT",
                        "default_value": "UNKNOWN",
                        "default_writer_va": "UNKNOWN",
                        "semantic_name": semantic,
                        "semantic_status": "PARTIAL",
                        "semantic_source_load_va": fmt_va(source_va),
                        "semantic_producer_va": "UNKNOWN",
                        "semantic_consumer_va": "UNKNOWN",
                        "semantic_evidence_span_start": fmt_va(wrapper_span[0]),
                        "semantic_evidence_span_end": fmt_va(wrapper_span[1]),
                        "semantic_evidence_span_sha256": wrapper_hash,
                        "semantic_support_spans": support_hashes,
                        "producer_va": "UNKNOWN",
                        "consumer_va": "UNKNOWN",
                        "consumer_slot": "N/A",
                        "codec_slot": "+0x34",
                        "write_site_va": fmt_va(source_va) if direction == "W" else "N/A",
                        "read_site_va": fmt_va(source_va) if direction == "R" else "N/A",
                        "file_offset": fmt_off(image.va_to_off(wire_call_va)),
                        "span_start": fmt_va(wrapper_span[0]),
                        "span_end": fmt_va(wrapper_span[1]),
                        "span_sha256": wrapper_hash,
                        "evidence_key": correction["evidence_key"],
                        "source": "IMAGE",
                        "conflicts_with": "",
                        "blocker": correction["blocker"],
                        "required_next_evidence": correction["required_next_evidence"],
                        "image_sha256": image.sha256,
                    }
                )

        if family == "U16_WRAPPER":
            extra_rows = [
                row for row in class_rows
                if row.get("direction(W/R)") in {"W", "R"}
                and row.get("new_file_off_claim") in ITEMBAG_UPPER_FALSE_FILE_OFFSETS
            ]
            if len(extra_rows) != 14:
                raise SystemExit("itembag_upper_false_frozen_row_census_mismatch_%s" % class_name)
            wrapper_hash = image.span_hash(*wrapper_span)
            for prior in extra_rows:
                append_correction(
                    class_name, prior, "REMOVE_NON_WIRE_POST_DECODE_TRAVERSAL_ROW",
                    "N/A", "N/A", "N/A", "N/A", "N/A", "0", "N/A",
                    prior["new_tag"], "N/A", "post_decode_container_traversal",
                    "NOT_WIRE", "NOT_WIRE", None, None, None, "N/A",
                    wrapper_span[0], wrapper_span[1], wrapper_hash,
                )

    corrections.sort(key=lambda row: (row["class"], row["base_row_ref"], row["delta_action"]))
    field_rows.sort(key=lambda row: (row["class"], row["direction"], int(row["order"]), row["wire_key"]))
    if (
        len(corrections) != 448
        or len(field_rows) != 84
        or len({row["correction_key"] for row in corrections}) != 448
        or len({row["evidence_key"] for row in corrections}) != 448
        or len({row["wire_key"] for row in field_rows}) != 84
        or Counter(row["delta_action"] for row in corrections)
        != Counter({
            "REMOVE_NON_WIRE_CONTROL_FLOW_ROW": 306,
            "REMOVE_NON_WIRE_POST_DECODE_TRAVERSAL_ROW": 56,
            "CORRECT_FIELD_LAYOUT": 84,
            "ANNOTATE_INHERITED_FIELD_ALIAS": 2,
        })
    ):
        raise SystemExit("itembag_correction_census_or_duplicate_mismatch")
    return corrections, field_rows


