    def parse_data(path: Path, expected_rows: int) -> tuple[list[dict[str, str]], list[tuple[int, int, str]]]:
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != EXPECTED_DATA_HASHES[path]:
            raise SystemExit("combat_lifecycle_data_hash_mismatch_%s" % path.name)
        text = raw.decode("utf-8", errors="strict")
        parsed = list(csv.DictReader(io.StringIO(text, newline=""), delimiter="\t"))
        if len(parsed) != expected_rows:
            raise SystemExit("combat_lifecycle_data_row_count_mismatch_%s" % path.name)
        lines = raw.splitlines(keepends=True)
        if len(lines) != expected_rows + 1:
            raise SystemExit("combat_lifecycle_data_physical_line_count_mismatch_%s" % path.name)
        offsets = []
        position = len(lines[0])
        for line in lines[1:]:
            offsets.append((position, position + len(line), hashlib.sha256(line).hexdigest()))
            position += len(line)
        return parsed, offsets

    equip_rows, equip_offsets = parse_data(EQUIP_VALUE_PATH, 17)
    behavior_rows, behavior_offsets = parse_data(BEHAVIOR_PATH, 2279)
