    rows: list[dict[str, str]] = []

    def image_span_text(name: str) -> str:
        start, end, span_hash = span_pins[name]
        return "%s..%s@file_off=%s..%s@sha256=%s" % (
            fmt_va(start), fmt_va(end), fmt_off(image.va_to_off(start)),
            fmt_off(image.va_to_off(end)), span_hash,
        )

    def add_image(
        lifecycle_id: str, row_kind: str, phase: str, predecessor: str,
        successor: str, order_relation: str, condition: str, observation: str,
        semantic_status: str, order_status: str, primary: str,
        support: tuple[str, ...], nonclaim: str, blocker: str,
        required_next: str,
    ) -> None:
        start, end, span_hash = span_pins[primary]
        support_text = ";".join(image_span_text(name) for name in support)
        values = {
            "row_kind": row_kind, "phase": phase, "predecessor": predecessor,
            "successor": successor, "order_relation": order_relation,
            "trigger_or_condition": condition, "exact_observation": observation,
            "semantic_status": semantic_status, "order_status": order_status,
            "source": "IMAGE", "nonclaim": nonclaim, "blocker": blocker,
            "required_next_evidence": required_next,
        }
        row = {
            "lifecycle_id": lifecycle_id,
            **values,
            "evidence_file": evidence_path(IMAGE_PATH),
            "evidence_file_sha256": image.sha256,
            "evidence_locator": "%s:%s" % (phase, primary),
            "evidence_span_start": fmt_va(start),
            "evidence_span_end": fmt_va(end),
            "evidence_span_start_file_offset": fmt_off(image.va_to_off(start)),
            "evidence_span_end_file_offset": fmt_off(image.va_to_off(end)),
            "evidence_span_sha256": span_hash,
            "support_spans": support_text,
            "image_sha256": image.sha256,
        }
        row["claim_sha256"] = combat_lifecycle_claim_sha(row)
        row["evidence_key"] = combat_lifecycle_evidence_key(row)
        row["lifecycle_key"] = combat_lifecycle_row_key(row)
        rows.append(row)

