        packed_sha = hashlib.sha256(packed).hexdigest()
        decoded = decode_pcz_bytes(packed)
        decoded_sha = hashlib.sha256(decoded).hexdigest()
        try:
            root = ET.fromstring(decoded)
        except ET.ParseError as exc:
            raise SystemExit(
                "monster_presentation_avatar_xml_malformed_%s" % path.name
            ) from exc
        nif_nodes = root.findall(".//NifFile")
        actions = root.findall(".//ActionList/Action")
        active_actions = [
            (index, action)
            for index, action in enumerate(actions)
            if action.attrib.get("Actived", "").casefold() == "true"
        ]
