    def staged_canonical(
        artifact_path: Path,
        columns: tuple[str, ...],
        candidates: list[dict[str, str]],
        selector: str,
        criteria: dict[str, str],
    ) -> tuple[str, str, dict[str, str]]:
        payload = _EXPECTED_OUTPUT_PAYLOADS.get(artifact_path.name)
        if payload is None:
            raise SystemExit(
                "monster_presentation_canonical_payload_not_staged_%s"
                % artifact_path.name
            )
        matches = [
            candidate for candidate in candidates
            if all(candidate.get(column) == value for column, value in criteria.items())
        ]
        if len(matches) != 1:
            raise SystemExit(
                "monster_presentation_canonical_selector_mismatch_%s" % selector
            )
        target = matches[0]
        return (
            hashlib.sha256(payload).hexdigest(),
            canonical_tsv_row_digest(artifact_path.name, columns, target),
            target,
        )

