    open_conflict_keys = {
        row["conflict_key"]
        for row in conflict_rows
        if row["resolution_status"].startswith("OPEN")
    }
    for row in conflict_rows:
        if row["rederived_evidence_key"] in field_evidence_keys:
            conflicts_by_evidence[row["rederived_evidence_key"]].append(
                row["conflict_key"]
            )
        elif row["field_key"] != "N/A":
            conflicts_by_field_fallback[row["field_key"]].append(
                row["conflict_key"]
            )
    for field in field_rows:
        matches = list(conflicts_by_evidence.get(field["evidence_key"], ()))
        matches.extend(
            conflicts_by_field_fallback.get(field["field_key"], ())
        )
        field["conflicts_with"] = ";".join(sorted(set(matches)))
        field["open_conflicts_with"] = ";".join(
            sorted(set(matches) & open_conflict_keys)
        )
    field_by_evidence = {row["evidence_key"]: row for row in field_rows}
